using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
internal static class DofusToolsUi {
 static TextBlock Label(string text,Brush ink){return new TextBlock{Text=text,Foreground=ink,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,7,0,7)};}
 static Button Button(string title,Action click){var b=new Button{Content=title,Padding=new Thickness(12,9,12,9),Margin=new Thickness(0,4,8,4)};b.Click+=delegate{click();};return b;}
 internal static void Options(StackPanel body,Panel actions,Store store,Action close,Action changed,Brush ink,Brush muted){var original=store.Value.dofus.overlay;var o=new DofusOverlayOptions{opacity=original.opacity,portrait=original.portrait,dofus=original.dofus,showPortrait=original.showPortrait,showDofus=original.showDofus,showProgress=original.showProgress,showNotes=original.showNotes};Action<string,bool,Action<bool>> toggle=(title,value,set)=>{bool active=value;var b=Button(title+(active?" ✓":""),()=>{});b.Click+=delegate{active=!active;set(active);b.Content=title+(active?" ✓":"");};body.Children.Add(b);};body.Children.Add(Label("Choisissez les éléments visibles et leurs proportions. Les changements s’appliquent après enregistrement.",muted));toggle("Afficher le personnage",o.showPortrait,v=>o.showPortrait=v);toggle("Afficher le Dofus",o.showDofus,v=>o.showDofus=v);toggle("Afficher la progression",o.showProgress,v=>o.showProgress=v);toggle("Afficher mes notes",o.showNotes,v=>o.showNotes=v);Action<string,double,double,double,Action<double>> slider=(name,value,min,max,set)=>{var label=Label(name+" · "+value,ink);var control=new Slider{Minimum=min,Maximum=max,Value=value,TickFrequency=1,IsSnapToTickEnabled=true,Margin=new Thickness(0,0,0,10)};control.ValueChanged+=delegate{label.Text=name+" · "+Math.Round(control.Value);set(control.Value);};body.Children.Add(label);body.Children.Add(control);};slider("Taille du personnage (px)",o.portrait,40,140,v=>o.portrait=(int)v);slider("Taille du Dofus (px)",o.dofus,32,96,v=>o.dofus=(int)v);slider("Opacité (%)",Math.Round(o.opacity*100),55,100,v=>o.opacity=v/100);var error=Label("",muted);body.Children.Add(error);actions.Children.Add(Button("Annuler",close));actions.Children.Add(Button("Enregistrer l’overlay",()=>{try{PersonalWorkflows.Change(store,()=>store.Value.dofus.overlay=o);changed();close();}catch(Exception ex){error.Text=ex.Message;}}));}
 internal static void Notes(StackPanel body,Panel actions,Store store,TougliStep step,Action close,Action changed,Brush ink,Brush muted){var draft=DofusTools.Note(store.Value,step);body.Children.Add(Label(step.Title,ink));body.Children.Add(Label("Mes notes pour cette étape",muted));var note=new TextBox{Text=draft.body,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=95,MaxLength=4000};body.Children.Add(note);body.Children.Add(Label("Préparation indiquée dans le guide",ink));body.Children.Add(Label("Ressources, prérequis et kamas sont repris uniquement lorsqu’ils figurent dans cette étape. Cochez ce qui est prêt ; votre inventaire n’est pas lu.",muted));var list=new StackPanel();body.Children.Add(list);var custom=new TextBox{Text=draft.custom,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=70,MaxLength=2000};Action draw=()=>{list.Children.Clear();draft.custom=custom.Text;var items=DofusTools.Prepare(step,draft.custom);if(items.Count==0)list.Children.Add(Label("Aucun préparatif précisé ici. Ajoutez les vôtres ci-dessous.",muted));foreach(string text in items){string key=DofusTools.ItemKey(text);bool done=draft.checkedItems.Contains(key);var b=Button((done?"✓ ":"○ ")+text,()=>{});b.HorizontalContentAlignment=HorizontalAlignment.Left;b.Click+=delegate{if(draft.checkedItems.Contains(key))draft.checkedItems.Remove(key);else draft.checkedItems.Add(key);b.Content=(draft.checkedItems.Contains(key)?"✓ ":"○ ")+text;};list.Children.Add(b);}};draw();body.Children.Add(Label("Mes préparatifs supplémentaires · un par ligne",muted));body.Children.Add(custom);body.Children.Add(Button("Actualiser ma liste",draw));var error=Label("",muted);body.Children.Add(error);actions.Children.Add(Button("Annuler",close));actions.Children.Add(Button("Enregistrer mes notes",()=>{try{draft.body=note.Text;draft.custom=custom.Text;draft.checkedItems=draft.checkedItems.Where(k=>DofusTools.Prepare(step,draft.custom).Any(t=>DofusTools.ItemKey(t)==k)).Distinct().ToList();DofusTools.SaveNote(store,draft);changed();close();}catch(Exception ex){error.Text=ex.Message;}}));}
}
